/**
 * 바비톡 스타일 아이콘 렌더링
 */
function renderBabitalkIcon($category, $icons, $color = '#6B5AED') {
    $svg = $icons[$category] ?? $icons['코'];

    // SVG에 색상 클래스 추가
    $svg_with_class = str_replace('<svg', '<svg class="babitalk-icon"', $svg);
    $svg_with_color = str_replace('currentColor', $color, $svg_with_class);

    return '<div class="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-white border border-gray-100 hover:border-purple-200 transition-all cursor-pointer">'
           . $svg_with_color
           . '</div>';
}
